import React from 'react';

export default function EventSalesFilterForm({ values, onChange, eventPlans }) {
  const dataOptions = ['전체', ...new Set(eventPlans.map(p => p.data))];
  const categoryOptions = ['전체', ...new Set(
    eventPlans
      .filter(p => !values.dataFilter || values.dataFilter === '전체' || p.data === values.dataFilter)
      .map(p => p.category)
  )];
  const planOptions = [
  { value: '', label: '전체' },
  ...eventPlans
    .filter(p => {
      // dataFilter가 설정된 경우 해당 데이터만 필터
      if (values.dataFilter && values.dataFilter !== '') {
        if (p.data !== values.dataFilter) return false;
      }
      // category가 설정된 경우 해당 카테고리만 필터
      if (values.category && values.category !== '') {
        if (p.category !== values.category) return false;
      }
      return true;
    })
    .map(p => ({
      value: p.id,
      label: `${p.name} (${p.monthlyFee.toLocaleString()}원)`
    }))
];

  return (
    <div className="mb-4 space-y-4">
      <Select
        label="데이터"
        name="dataFilter"
        options={dataOptions.map(opt => ({ value: opt === '전체' ? '' : opt, label: opt }))}
        value={values.dataFilter}
        onChange={onChange}
      />
      <Select
        label="카테고리"
        name="category"
        options={categoryOptions.map(opt => ({ value: opt === '전체' ? '' : opt, label: opt }))}
        value={values.category}
        onChange={onChange}
      />
      <Select
        label="요금제"
        name="planId"
        options={planOptions}
        value={values.planId}
        onChange={onChange}
      />
    </div>
  );
}

function Select({ label, name, options, value, onChange }) {
  return (
    <div>
      <label className="block text-sm font-medium mb-1">{label}</label>
      <select
        name={name}
        value={value}
        onChange={e => onChange(name, e.target.value)}
        className="w-full border p-2 rounded"
      >
        {options.map(opt => (
          <option key={opt.value} value={opt.value}>{opt.label}</option>
        ))}
      </select>
    </div>
  );
}