/* File: src/calculators/EventSalesResult.jsx */
import React from 'react';

export default function EventSalesResult({ monthlyPlan, deviceInstallment, totalPayment, savings }) {
  return (
    <div className="mt-4 p-4 bg-gray-100 rounded space-y-2">
      <p className="text-lg">월 요금제: <strong>{monthlyPlan.toLocaleString()}원</strong></p>
      <p className="text-lg">단말 할부 대금: <strong>{deviceInstallment.toLocaleString()}원</strong></p>
      <p className="text-lg">월 총 납부 예상 금액: <strong>{totalPayment.toLocaleString()}원</strong></p>
      {savings >= 0 ? (
        <p className="text-lg text-green-600">요금할인 절감액: +{savings.toLocaleString()}원</p>
      ) : (
        <p className="text-lg text-red-600">지원금 절감액: -{Math.abs(savings).toLocaleString()}원</p>
      )}
      <p className="text-sm font-bold text-red-500">주의! 본 견적은 결합 적용 안 된 결과 값 입니다.</p>
    </div>
  );
}
